pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < address(this).balance + 1 ether);
        Reverter helper = new Reverter();
        address depositor = address(helper);
        vm.assume(depositor != address(c));

        vm.deal(address(this), amount);
        // deposit through the fallback, routed via the adversarial helper's
        // accepting deposit path (its fallback only reverts when paid by c)
        (bool depOk, ) = depositor.call{value: amount}("");
        assertTrue(depOk);
        assertEq(c.balances(depositor), amount);

        uint256 before = address(c).balance;
        vm.prank(depositor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // General rule: a withdraw either reverts, or it succeeds AND the
        // contract's Ether balance decreased by the caller's full balance.
        assertTrue(!ok || address(c).balance == before - c.balances(depositor) - 0 && c.balances(depositor) == 0 && address(c).balance == before - amount);
    }
}

contract Reverter {
    fallback() external payable {
        // accept deposits from anyone except C, but reject payments from C
        if (msg.sender == address(0x0)) revert();
        assembly {
            if eq(caller(), sload(0)) { revert(0, 0) }
        }
        // store C's address on first interaction so later payouts revert
        assembly {
            if iszero(sload(0)) { sstore(0, caller()) }
        }
    }
}

