pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(address(c));
    }

    function testFuzz_property(uint256 amt) public {
        amt = bound(amt, 1, 1e18);
        vm.deal(address(this), amt);
        attacker.deposit{value: amt}();
        attacker.withdraw();
        // P: the re-entrant withdraw fails, so the balance is paid out exactly once:
        // c's remaining ether == deposits - recorded balances.
        // M: the re-entrant withdraw succeeds and pays the balance twice, so c's
        // remaining ether is amt - 2*balance, violating the rule.
        assertTrue(address(c).balance == amt - c.balances(address(attacker)));
    }
}

contract Attacker {
    address immutable c;

    constructor(address _c) {
        c = _c;
    }

    function deposit() external payable {
        address(c).call{value: msg.value}("");
    }

    function withdraw() external {
        address(c).call(abi.encodeWithSignature("withdraw()"));
    }

    receive() external payable {
        // re-enter withdraw, ignoring whether it succeeds
        address(c).call(abi.encodeWithSignature("withdraw()"));
    }
}
}

