pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt) public {
        // keep the amount admissible: a real deposit of value the contract can pay out
        bound(amt, 1, 1 ether);

        Attacker a = new Attacker(c);
        vm.deal(address(a), amt);

        // deposit amt into c via the payable fallback
        a.deposit{value: amt}();
        assert(address(c).balance == amt);

        // withdraw once; attacker's receive() re-enters withdraw but catches failure
        a.attack();

        // Rule: one withdrawal pays the recorded balance exactly once.
        // Reference C: inner re-entrant withdraw reverts (lock), caught -> attacker holds amt.
        // Mutant M: lock never set, re-entrant withdraw succeeds -> attacker holds 2*amt.
        assertTrue(address(a).balance == amt);
    }
}

contract Attacker {
    C c;
    bool reentered;
    constructor(C _c) { c = _c; }
    function deposit() external payable {
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok);
    }
    function attack() external {
        reentered = false;
        c.withdraw();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            try c.withdraw() {} catch {}
        }
    }
}

